using System.Text;
using UnityEditor;
using UnityEngine;

public class FishReelTune
{
    public static void Run()
    {
        UnityEngine.Object config = AssetDatabase.LoadAssetAtPath<UnityEngine.Object>("Assets/Data/Config/HookConfig.asset");
        SerializedObject serialized = new SerializedObject(config);
        SerializedProperty reel = serialized.FindProperty("ReelSpeedMeters");
        SerializedProperty width = serialized.FindProperty("LineWidthMeters");

        reel.floatValue = 4.5f;
        serialized.ApplyModifiedPropertiesWithoutUndo();
        EditorUtility.SetDirty(config);
        AssetDatabase.SaveAssets();

        Debug.Log("[FishReelTune] ReelSpeed=" + reel.floatValue + " LineWidth=" + width.floatValue);
    }
}
